/**
 * Helpers - Utility functions
 * 
 * Responsibilities:
 * - Format file sizes
 * - Format dates
 * - Validate inputs
 * - Other reusable utility functions
 */

/**
 * Format bytes to human-readable size
 */
export const formatFileSize = bytes => {
  if (!bytes || bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`;
};

/**
 * Format date to readable string
 */
export const formatDate = dateString => {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

/**
 * Get file icon based on mime type
 */
export const getFileIcon = mimeType => {
  if (!mimeType) return '📎';
  const type = mimeType.toLowerCase();

  // Images
  if (type.startsWith('image/')) {
    if (type.includes('jpeg') || type.includes('jpg')) return '🖼️';
    if (type.includes('png')) return '🖼️';
    if (type.includes('gif')) return '🖼️';
    return '🖼️';
  }

  // PDF
  if (type === 'application/pdf' || type.includes('pdf')) return '📄';

  // Documents
  if (type.includes('word') || type.includes('document')) return '📝';
  if (type.includes('excel') || type.includes('spreadsheet')) return '📊';
  if (type.includes('powerpoint') || type.includes('presentation')) return '📊';
  if (type.includes('text')) return '📄';

  // Archives
  if (type.includes('zip') || type.includes('rar') || type.includes('tar')) return '📦';

  // Video
  if (type.startsWith('video/')) return '🎥';

  // Audio
  if (type.startsWith('audio/')) return '🎵';
  return '📎';
};

